<script setup lang="ts">
import { ArrowLeft, ArrowRight, CalendarDays, Check, Clock3, CreditCard, LockKeyhole } from '@lucide/vue'
import type { AvailabilitySlot, PublicCatalog, ServiceCard as Service } from '~~/shared/types/catalog'
import { totalScheduledDurationMinutes } from '~~/shared/utils/service-duration'
import { SALON_TIMEZONE, formatXof } from '~~/shared/constants/business'
definePageMeta({title:'Réservation'})
const route=useRoute(),{data:catalog}=await useFetch<PublicCatalog>('/api/public/catalog',{key:'public-catalog'})
const steps=['Prestations','Créneau','Vos coordonnées','Confirmation'],step=ref(0),selectedIds=ref<string[]>([]),selectedStaff=ref(''),chosenDate=ref(new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())),chosenSlot=ref<AvailabilitySlot|null>(null),staffOptions=ref<Array<{id:string;firstName:string;lastName:string|null;bio:string|null}>>([]),slots=ref<AvailabilitySlot[]>([]),loadingAvailability=ref(false),availabilityConfigured=ref(false),saving=ref(false),errorMessage=ref(''),idempotencyKey=ref(crypto.randomUUID())
const form=reactive({firstName:'',lastName:'',phone:'',whatsapp:'',email:'',note:'',termsAccepted:false,website:''})
const selectedServices=computed<Service[]>(()=>catalog.value?.services.filter((item)=>selectedIds.value.includes(item.id))??[]),totalXof=computed(()=>selectedServices.value.reduce((sum,item)=>sum+item.priceXof,0)),depositXof=computed(()=>Math.min(totalXof.value,selectedServices.value.reduce((sum,item)=>sum+item.depositXof,0))),totalMinutes=computed(()=>totalScheduledDurationMinutes(selectedServices.value)),selectionKey=computed(()=>selectedIds.value.slice().sort().join(',')),displayedSlots=computed(()=>{const byTime=new Map<string,AvailabilitySlot>();for(const item of slots.value)if(!byTime.has(item.startsAt))byTime.set(item.startsAt,item);return[...byTime.values()]}),canReserve=computed(()=>Boolean(catalog.value&&!catalog.value.demo&&availabilityConfigured.value)),introCopy=computed(()=>catalog.value?.demo?'Les prestations ci-dessous sont des exemples éditoriaux. Le salon doit ajouter son calendrier et ses informations avant d’accepter des rendez-vous.':'Choisissez une prestation, puis un créneau disponible calculé selon le calendrier du salon.')
function toggleService(id:string){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter((value)=>value!==id):[...selectedIds.value,id];chosenSlot.value=null}
function localTime(iso:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,hour:'2-digit',minute:'2-digit'}).format(new Date(iso))}
function serviceNames(items:Service[]){return items.map((item)=>item.name).join(' · ')}
async function loadStaffAndSlots(){chosenSlot.value=null;slots.value=[];errorMessage.value='';if(!selectionKey.value||catalog.value?.demo)return;loadingAvailability.value=true;try{const staffResult=await $fetch<{configured:boolean;staff:Array<{id:string;firstName:string;lastName:string|null;bio:string|null}>}>('/api/public/staff',{query:{services:selectionKey.value}});staffOptions.value=staffResult.staff;const slotResult=await $fetch<{configured:boolean;slots:AvailabilitySlot[]}>('/api/public/availability',{query:{date:chosenDate.value,services:selectionKey.value,...(selectedStaff.value?{staffId:selectedStaff.value}:{})}});availabilityConfigured.value=slotResult.configured;slots.value=slotResult.slots}catch(error){availabilityConfigured.value=false;errorMessage.value=error instanceof Error?error.message:'Le calendrier est indisponible.'}finally{loadingAvailability.value=false}}
watch([selectionKey,chosenDate,selectedStaff],loadStaffAndSlots)
watch([()=>route.query.service,()=>catalog.value?.services],()=>{const slug=typeof route.query.service==='string'?route.query.service:'';const item=catalog.value?.services.find((service)=>service.slug===slug);if(item&&!selectedIds.value.includes(item.id))selectedIds.value.push(item.id)},{immediate:true})
function continueToSlot(){errorMessage.value='';if(!selectedIds.value.length){errorMessage.value='Choisissez au moins une prestation.';return}step.value=1}
function continueToDetails(){errorMessage.value='';if(!chosenSlot.value){errorMessage.value='Choisissez un créneau disponible.';return}step.value=2}
function continueToSummary(){errorMessage.value='';if(!form.firstName.trim()||!form.lastName.trim()||!form.phone.trim()){errorMessage.value='Renseignez votre prénom, votre nom et un numéro béninois.';return}if(!form.termsAccepted){errorMessage.value='Acceptez les conditions pour poursuivre.';return}step.value=3}
async function submitBooking(){errorMessage.value='';if(!canReserve.value||!chosenSlot.value){errorMessage.value='Le calendrier du salon n’est pas prêt ou ce créneau n’est plus disponible.';return}saving.value=true;try{const result=await $fetch<{ok:boolean;booking:{id:string;reference:string;status:string;guestAccessToken:string};checkoutUrl?:string}>('/api/bookings',{method:'POST',body:{serviceIds:selectedIds.value,staffId:selectedStaff.value||chosenSlot.value.staffId,startsAt:chosenSlot.value.startsAt,firstName:form.firstName,lastName:form.lastName,phone:form.phone,whatsapp:form.whatsapp||'',email:form.email||'',note:form.note,termsAccepted:form.termsAccepted,idempotencyKey:idempotencyKey.value,portfolioItemId:typeof route.query.reference==='string'?route.query.reference:null,website:form.website}});sessionStorage.setItem('onglerie-guest-token',result.booking.guestAccessToken);sessionStorage.setItem('onglerie-booking-id',result.booking.id);sessionStorage.setItem('onglerie-booking-ref',result.booking.reference);if(result.checkoutUrl){window.location.assign(result.checkoutUrl);return}await navigateTo('/reservation/confirmation')}catch(error){const data=(error as{data?:{statusMessage?:string;message?:string}})?.data;errorMessage.value=data?.statusMessage||data?.message||(error instanceof Error?error.message:'La réservation n’a pas pu être enregistrée.');chosenSlot.value=null;await loadStaffAndSlots()}finally{saving.value=false}}
const title='Réserver un rendez-vous — Votre onglerie',description='Choisissez vos prestations, consultez les créneaux réels et réservez au Bénin.'
useSeoMeta({title,description,ogTitle:title,ogDescription:description,ogType:'website',robots:'noindex, nofollow'})
</script>
<template><div class="container-page reservation-page"><PageIntro eyebrow="Votre moment" title="La beauté, à votre rythme." :description="introCopy"/><div v-if="catalog?.demo" class="demo-note reservation-demo">Démo : prestations, prix et images sont des exemples. La prise de rendez-vous reste désactivée tant que l’équipe n’a pas enregistré ses prestations, horaires et disponibilités.</div><div class="stepper" aria-label="Étapes de la réservation"><div v-for="(label,index) in steps" :key="label" :class="['stepper__item',{'is-current':step===index,'is-done':step>index}]" :aria-current="step===index?'step':undefined"><span>{{step>index?'✓':`0${index+1}`}}</span><small>{{label}}</small></div></div><form class="reservation-layout" @submit.prevent="step===2?continueToSummary():step===3?submitBooking():undefined"><div class="reservation-main">
<section v-if="step===0" class="reservation-panel"><div class="panel-heading"><span class="section-kicker">01 · Votre pose</span><h2 class="display">Ce qui vous fait envie.</h2><p>Vous pouvez combiner jusqu’à six prestations proposées par le salon.</p></div><div class="service-options"><label v-for="service in catalog?.services" :key="service.id" :class="['service-option',{'is-selected':selectedIds.includes(service.id)}]"><input type="checkbox" :checked="selectedIds.includes(service.id)" :disabled="catalog?.demo" @change="toggleService(service.id)"><span class="service-option__check"><Check :size="14"/></span><span class="service-option__copy"><strong>{{service.name}}</strong><small>{{service.category}} · {{service.durationMinutes}} min</small></span><span class="service-option__price">{{formatXof(service.priceXof)}}</span></label><div v-if="!catalog?.services.length" class="empty-state">Aucune prestation n’est publiée pour le moment.</div></div><button class="btn btn-primary" type="button" :disabled="!selectedIds.length||catalog?.demo" @click="continueToSlot">Choisir un créneau <ArrowRight :size="16"/></button></section>
<section v-else-if="step===1" class="reservation-panel"><button type="button" class="back-button" @click="step=0"><ArrowLeft :size="14"/> Modifier les prestations</button><div class="panel-heading"><span class="section-kicker">02 · Disponibilités</span><h2 class="display">Quand vous convient-il&nbsp;?</h2><p>Les créneaux affichés proviennent des horaires et rendez-vous enregistrés par le salon.</p></div><div class="form-row"><label class="form-field"><span>Date du rendez-vous</span><input v-model="chosenDate" class="form-control" type="date" :min="new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())" :disabled="!canReserve"></label><label class="form-field"><span>Professionnelle</span><select v-model="selectedStaff" class="form-control" :disabled="!staffOptions.length||!canReserve"><option value="">Première professionnelle disponible</option><option v-for="person in staffOptions" :key="person.id" :value="person.id">{{person.firstName}} {{person.lastName||''}}</option></select></label></div><div v-if="loadingAvailability" class="empty-state">Recherche des créneaux réels…</div><div v-else-if="!availabilityConfigured&&!catalog?.demo" class="empty-state">Le salon n’a pas encore configuré son calendrier de réservation.</div><div v-else-if="!displayedSlots.length&&!catalog?.demo" class="empty-state">Aucun créneau disponible à cette date. Choisissez une autre journée ou modifiez les prestations.</div><div v-else class="slot-list"><button v-for="slot in displayedSlots" :key="slot.startsAt" type="button" :class="['slot-button',{'is-selected':chosenSlot?.startsAt===slot.startsAt}]" @click="chosenSlot=slot"><CalendarDays :size="15"/> {{localTime(slot.startsAt)}}<small>{{slot.staffName||'Équipe disponible'}}</small></button></div><button class="btn btn-primary" type="button" :disabled="!chosenSlot||catalog?.demo" @click="continueToDetails">Continuer <ArrowRight :size="16"/></button></section>
<section v-else-if="step===2" class="reservation-panel"><button type="button" class="back-button" @click="step=1"><ArrowLeft :size="14"/> Revenir au créneau</button><div class="panel-heading"><span class="section-kicker">03 · Vos coordonnées</span><h2 class="display">À qui réservons-nous&nbsp;?</h2><p>La réservation invitée ne nécessite pas la création d’un compte.</p></div><div class="form-row"><label class="form-field"><span>Prénom *</span><input v-model="form.firstName" class="form-control" autocomplete="given-name" required maxlength="80"></label><label class="form-field"><span>Nom *</span><input v-model="form.lastName" class="form-control" autocomplete="family-name" required maxlength="80"></label></div><label class="form-field"><span>Téléphone béninois *</span><input v-model="form.phone" class="form-control" type="tel" autocomplete="tel" placeholder="+229 97 00 00 00" required></label><label class="form-field"><span>WhatsApp (facultatif, si différent)</span><input v-model="form.whatsapp" class="form-control" type="tel" placeholder="+229 …"></label><label class="form-field"><span>E-mail (facultatif)</span><input v-model="form.email" class="form-control" type="email" autocomplete="email"></label><label class="form-field"><span>Notes pour l’équipe (facultatif)</span><textarea v-model="form.note" class="form-control" rows="4" maxlength="800" placeholder="Précision utile à la préparation de votre rendez-vous…"/></label><label class="website-field" aria-hidden="true">Votre site web<input v-model="form.website" tabindex="-1" autocomplete="off"></label><button class="btn btn-primary" type="button" @click="continueToSummary">Vérifier le récapitulatif <ArrowRight :size="16"/></button></section>
<section v-else class="reservation-panel"><button type="button" class="back-button" @click="step=2"><ArrowLeft :size="14"/> Modifier mes coordonnées</button><div class="panel-heading"><span class="section-kicker">04 · Vérifier avant de confirmer</span><h2 class="display">Tout est juste&nbsp;?</h2><p>Le montant et le statut seront recalculés et vérifiés côté serveur.</p></div><div class="final-summary"><p><span>Prestations</span><strong>{{serviceNames(selectedServices)}}</strong></p><p><span>Date</span><strong>{{chosenSlot?new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'full'}).format(new Date(chosenSlot.startsAt)):''}}</strong></p><p><span>Heure</span><strong>{{chosenSlot?localTime(chosenSlot.startsAt):''}} · {{chosenSlot?.staffName||'Première professionnelle disponible'}}</strong></p><p><span>Durée totale avec préparation</span><strong>{{totalMinutes}} min</strong></p><p><span>Total</span><strong>{{formatXof(totalXof)}}</strong></p><p><span>Acompte indiqué</span><strong>{{formatXof(depositXof)}}</strong></p><p><span>Solde estimé</span><strong>{{formatXof(Math.max(0,totalXof-depositXof))}}</strong></p></div><label class="consent"><input v-model="form.termsAccepted" type="checkbox" required><span>J’accepte les <NuxtLink to="/conditions-generales" target="_blank">conditions de réservation</NuxtLink> et la <NuxtLink to="/politique-confidentialite" target="_blank">politique de confidentialité</NuxtLink>.</span></label><button class="btn btn-primary" type="submit" :disabled="saving||!form.termsAccepted||!canReserve">{{saving?'Enregistrement sécurisé…':depositXof?'Réserver et payer l’acompte':'Confirmer le rendez-vous'}} <CreditCard :size="16"/></button><p class="privacy-hint"><LockKeyhole :size="13"/> Le paiement n’est confirmé qu’après rapprochement serveur.</p></section><p v-if="errorMessage" class="form-feedback" role="alert">{{errorMessage}}</p></div><aside class="booking-summary surface-card"><span class="section-kicker">Votre récapitulatif</span><h3 class="display">En un regard.</h3><template v-if="selectedServices.length"><div v-for="item in selectedServices" :key="item.id" class="summary-line"><span>{{item.name}}<small><Clock3 :size="12"/> {{item.durationMinutes}} min</small></span><strong>{{formatXof(item.priceXof)}}</strong></div><hr><div class="summary-line summary-line--total"><span>Total</span><strong>{{formatXof(totalXof)}}</strong></div><div class="summary-line"><span>Acompte affiché</span><strong>{{formatXof(depositXof)}}</strong></div><div class="summary-line"><span>Solde estimé</span><strong>{{formatXof(Math.max(0,totalXof-depositXof))}}</strong></div></template><p v-else class="summary-empty">Les prestations sélectionnées apparaîtront ici.</p><p class="summary-trust"><LockKeyhole :size="14"/> Pas de confirmation sur simple retour du site de paiement.</p></aside></form><div class="booking-support"><span><LockKeyhole :size="14"/> Connexion chiffrée</span><span><Clock3 :size="14"/> Durée de retenue définie par le salon</span></div></div></template>
<style scoped>.reservation-page{padding-bottom:2rem}.reservation-demo{margin:0 auto 1.5rem}.stepper{display:grid;grid-template-columns:repeat(4,1fr);margin:0 auto 1.5rem;max-width:850px}.stepper__item{position:relative;display:flex;align-items:center;gap:.6rem;color:#978982}.stepper__item:not(:last-child)::after{position:absolute;top:16px;left:50px;width:calc(100% - 60px);height:1px;background:var(--line);content:''}.stepper__item>span{display:grid;width:33px;height:33px;flex:0 0 auto;place-items:center;border:1px solid var(--line);border-radius:50%;background:var(--page);font-size:.67rem}.stepper__item small{font-size:.65rem}.stepper__item.is-current{color:var(--merlot)}.stepper__item.is-current>span,.stepper__item.is-done>span{border-color:var(--merlot);color:white;background:var(--merlot)}.reservation-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.7fr);align-items:start;gap:1.3rem}.reservation-main,.booking-summary{border-radius:1.2rem;background:var(--paper)}.reservation-main{border:1px solid var(--line);padding:clamp(1.25rem,3vw,2.4rem)}.reservation-panel{display:grid;gap:1.2rem}.panel-heading h2,.booking-summary h3{margin:.4rem 0;font-size:clamp(2.4rem,4vw,3.5rem)}.panel-heading p{margin:.4rem 0;color:var(--muted);font-size:.76rem}.service-options{display:grid;gap:.6rem}.service-option{display:flex;align-items:center;gap:.8rem;border:1px solid var(--line);border-radius:.9rem;padding:.85rem 1rem;cursor:pointer;transition:.2s}.service-option.is-selected{border-color:var(--merlot);background:#fbf5f2}.service-option input{position:absolute;opacity:0}.service-option__check{display:grid;width:21px;height:21px;flex:0 0 auto;place-items:center;border:1px solid #cbbeb4;border-radius:50%;color:transparent}.service-option.is-selected .service-option__check{border-color:var(--merlot);color:white;background:var(--merlot)}.service-option__copy{display:grid;flex:1;gap:.12rem}.service-option__copy strong{font-size:.77rem}.service-option__copy small{color:var(--muted);font-size:.62rem}.service-option__price{color:var(--merlot);font-size:.72rem;font-weight:700}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.form-field{display:grid;gap:.4rem}.form-field>span{color:#4c403c;font-size:.71rem;font-weight:700}.form-control{font-size:.77rem}.slot-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:.5rem}.slot-button{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:.3rem;border:1px solid var(--line);border-radius:.7rem;padding:.7rem;color:var(--ink);background:white;font-size:.74rem;text-align:left;cursor:pointer}.slot-button small{grid-column:2;color:var(--muted);font-size:.57rem}.slot-button.is-selected{border-color:var(--merlot);color:var(--merlot);background:#fbf2f4}.back-button{display:inline-flex;align-items:center;gap:.45rem;border:0;padding:0;color:var(--muted);background:none;font-size:.68rem;cursor:pointer}.final-summary{display:grid;gap:0;border-block:1px solid var(--line);padding:.3rem 0}.final-summary p{display:flex;justify-content:space-between;gap:1rem;margin:.55rem 0;color:var(--muted);font-size:.7rem}.final-summary strong{max-width:65%;color:var(--ink);text-align:right}.consent{display:flex;align-items:flex-start;gap:.6rem;color:var(--muted);font-size:.68rem}.consent input{margin-top:.2rem;accent-color:var(--merlot)}.consent a{color:var(--merlot);text-decoration:underline}.privacy-hint{display:flex;align-items:start;gap:.45rem;margin:0;color:var(--muted);font-size:.62rem}.privacy-hint svg{flex:0 0 auto}.booking-summary{position:sticky;top:95px;padding:1.35rem}.booking-summary h3{font-size:2.4rem}.summary-line{display:flex;justify-content:space-between;gap:.5rem;padding:.85rem 0;border-bottom:1px solid var(--line);font-size:.71rem}.summary-line span{display:grid;gap:.2rem}.summary-line small{display:flex;align-items:center;gap:.3rem;color:var(--muted);font-size:.59rem}.summary-line strong{color:var(--merlot);font-size:.72rem}.summary-line--total{border:0;font-size:.86rem}.summary-empty{color:var(--muted);font-size:.7rem}.summary-trust{display:flex;align-items:start;gap:.45rem;margin:1rem 0 0;color:var(--muted);font-size:.6rem}.summary-trust svg{flex:0 0 auto;color:var(--merlot)}.booking-support{display:flex;justify-content:center;gap:1.4rem;padding:1.2rem;color:var(--muted);font-size:.62rem}.booking-support span{display:flex;align-items:center;gap:.4rem}.form-feedback{margin:.6rem 0 0;color:#913b47;font-size:.75rem}.website-field{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}@media(max-width:850px){.reservation-layout{grid-template-columns:1fr}.booking-summary{position:static;order:-1}.booking-support{flex-direction:column;align-items:center;gap:.45rem}}@media(max-width:560px){.stepper{gap:.25rem}.stepper__item{display:grid;justify-items:center;gap:.2rem}.stepper__item:not(:last-child)::after{top:16px;left:calc(50% + 20px);width:calc(100% - 22px)}.stepper__item small{font-size:.57rem}.form-row{grid-template-columns:1fr}.booking-summary{padding:1rem}}
</style>
